 public static async Task RunAsync(HttpClient http,string orderConnection,string staffConnection,int staffPort,string key,long branch,string admin,string customer,(long User,string Token)[] workers)
 {
  if(!Regex.IsMatch(new MySqlConnectionStringBuilder(orderConnection).Database,"^cleanhome_test_[a-f0-9]{12}_order$"))throw new Exception("QA database required");
  await using var orders=new MySqlConnection(orderConnection);await orders.OpenAsync();await using var staff=new MySqlConnection(staffConnection);await staff.OpenAsync();
  using var direct=new HttpClient{BaseAddress=new Uri($"http://127.0.0.1:{staffPort}"),Timeout=TimeSpan.FromSeconds(15)};direct.DefaultRequestHeaders.Add("X-CleanHome-Service-Key",key);
  var ids=new List<long>();foreach(var worker in workers){await using var q=staff.Sql("SELECT id FROM employees WHERE user_id=@id",("id",worker.User));ids.Add(Convert.ToInt64(await q.ExecuteScalarAsync()));}
  var start=DateTime.UtcNow.Date.AddDays(8).AddHours(2);var sequence=100L;
  foreach(var id in ids){await using var q=staff.Sql("INSERT INTO employee_availability(employee_id,starts_at,ends_at,status) VALUES(@id,@start,@end,'available')",("id",id),("start",DateTime.UtcNow.Date.AddDays(-1)),("end",start.AddDays(25)));await q.ExecuteNonQueryAsync();}
  for(var i=0;i<workers.Length;i++)await SetPresence(i,true);
  var one=await Register(1,0);var offers=await Task.WhenAll(workers.Select(w=>Offer(w.Token,one)));
  Check(offers.All(o=>!o.TryGetProperty("latitude",out _)&&!o.TryGetProperty("addressText",out _)),"invites never expose exact destination");
  await Request("GET","/api/orders/staff/orders/"+one+"/destination",404,token:workers[0].Token);
  var keys=workers.Select(_=>Guid.NewGuid().ToString("N")).ToArray();
  var race=await Task.WhenAll(workers.Select((w,i)=>Accept(w.Token,offers[i].GetProperty("id").GetInt64(),keys[i])));
  Check(race.Count(r=>r.Status==200)==1,"one final slot has exactly one winner");var winner=Array.FindIndex(race,r=>r.Status==200);
  var replay=await Accept(workers[winner].Token,offers[winner].GetProperty("id").GetInt64(),keys[winner]);Check(replay.Status==200&&replay.Body.GetProperty("id").GetString()==race[winner].Body.GetProperty("id").GetString(),"lost claim response replay resolves same operation");
  Check(await Assigned(one)==1,"no duplicate assignments");await Request("GET","/api/orders/staff/orders/"+one+"/destination",200,token:workers[winner].Token);
  await Request("GET","/api/orders/staff/orders/"+one+"/destination",404,token:workers[(winner+1)%3].Token);
  Console.WriteLine("PASS: GPS invitations hide coordinates, final-slot race, duplicate claim replay and post-claim address authorization.");
  var multi=await Register(3,1);var multiOffers=await Task.WhenAll(workers.Select(w=>Offer(w.Token,multi)));
  Check((await Accept(workers[0].Token,multiOffers[0].GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))).Status==200,"first multi-person claim");
  var jobs=await Request("GET","/api/staff/me/jobs",200,token:workers[0].Token);var assignment=jobs.EnumerateArray().Single(j=>j.GetProperty("bookingId").GetInt64()==multi).GetProperty("id").GetInt64();
  await Request("POST",$"/api/orders/staff/orders/{multi}/progress",409,new{idempotencyKey=Guid.NewGuid().ToString("N"),assignmentId=assignment,nextStatus="in_progress"},workers[0].Token);
  for(var i=1;i<3;i++)Check((await Accept(workers[i].Token,multiOffers[i].GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))).Status==200,"remaining multi-person slot");
  Check(await Assigned(multi)==3,"multi-person capacity exact");
  Console.WriteLine("PASS: three-person recruitment preserves outstanding invites and refuses starting while understaffed.");
  var overlap1=await Register(1,2);var overlap2=await Register(1,2);var overlapOffers=await Task.WhenAll(new[]{Offer(workers[0].Token,overlap1),Offer(workers[0].Token,overlap2)});
  var collisions=await Task.WhenAll(overlapOffers.Select(o=>Accept(workers[0].Token,o.GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))));Check(collisions.Count(r=>r.Status==200)==1,"employee cannot claim overlapping bookings concurrently");
  var expires=await Register(1,3);var expired=await Offer(workers[1].Token,expires);await using(var q=staff.Sql("UPDATE dispatch_offers SET expires_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND) WHERE id=@id",("id",expired.GetProperty("id").GetInt64())))await q.ExecuteNonQueryAsync();
  Check((await Accept(workers[1].Token,expired.GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))).Status==409,"server refuses expired invitation");
  var offJob=await Register(1,4);var offOffer=await Offer(workers[2].Token,offJob);await SetPresence(2,false);Check((await Accept(workers[2].Token,offOffer.GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))).Status==409,"readiness is rechecked inside claim");await SetPresence(2,true);
  var manual=await Register(1,5);var selfOffer=await Offer(workers[0].Token,manual);
  var manualRace=await Task.WhenAll(Accept(workers[0].Token,selfOffer.GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N")),Operation("/api/orders/admin/orders/"+manual+"/assignments",admin,new{idempotencyKey=Guid.NewGuid().ToString("N"),employeeIds=new[]{ids[1]},requiredSkillIds=Array.Empty<long>()}));
  Check(manualRace.Count(r=>r.Status==200)==1&&await Assigned(manual)==1,"admin fallback and self-claim share slot lock");
  var cancelled=await Register(1,6);var cancelOffer=await Offer(workers[0].Token,cancelled);var cancellation=await Request("POST",$"/api/orders/me/{cancelled}/cancellations",201,new{reason="QA cancel before claim"},customer);
  Check((await Accept(workers[0].Token,cancelOffer.GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))).Status==409,"pending cancellation blocks claims");
  var approved=await Operation($"/api/orders/admin/orders/{cancelled}/cancellations/{cancellation.GetProperty("id").GetInt64()}/approve",admin,new{idempotencyKey=Guid.NewGuid().ToString("N")});Check(approved.Status==200,"cancel workflow");
  Check((await Accept(workers[0].Token,cancelOffer.GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))).Status==409&&await Assigned(cancelled)==0,"cancelled job cannot gain assignments");
  using(var lateRegister=await direct.PostAsJsonAsync("/internal/dispatch",new{bookingId=cancelled,code="D-QA-"+cancelled,branchId=branch,area="QA area",serviceId=77,serviceName="QA cleaning",start=start.AddDays(6),end=start.AddDays(6).AddHours(1),amount=600000,requiredStaff=1,latitude=10.7769m,longitude=106.7009m}))Check((int)lateRegister.StatusCode==409,"late registration cannot resurrect a cancelled booking");
  await Request("PUT","/api/staff/me/dispatch/presence",400,new{ready=true,latitude=10.7,longitude=106.7,accuracy=99999,observedAt=DateTimeOffset.UtcNow},workers[0].Token);
  await Request("PUT","/api/staff/me/dispatch/presence",400,new{ready=true,latitude=10.7,longitude=106.7,accuracy=20,observedAt=DateTimeOffset.UtcNow.AddHours(-1)},workers[0].Token);
  await using(var outside=staff.Sql("UPDATE employee_presence SET latitude=20 WHERE employee_id=@id",("id",ids[0])))await outside.ExecuteNonQueryAsync();
  var distant=await Register(1,7);await Offer(workers[1].Token,distant);var distantList=await Request("GET","/api/staff/me/dispatch/offers",200,token:workers[0].Token);Check(!distantList.EnumerateArray().Any(o=>o.GetProperty("bookingId").GetInt64()==distant),"outside-radius staff not invited");await SetPresence(0,true);
  var unavailableSkill=await Request("POST","/api/staff/admin/skills",201,new{name="Dispatch special QA",description="Required for dispatch QA only"},admin);
  await Request("PUT","/api/staff/admin/dispatch/services/77/skills",204,new[]{unavailableSkill.GetProperty("id").GetInt64()},admin);
  var skillJob=await Register(1,8);for(var scan=0;scan<20;scan++){using var response=await direct.GetAsync("/internal/dispatch/"+skillJob);var status=await response.Content.ReadFromJsonAsync<JsonElement>();if(status.GetProperty("round").GetInt32()>0)break;await Task.Delay(500);}foreach(var worker in workers){var invitations=await Request("GET","/api/staff/me/dispatch/offers",200,token:worker.Token);Check(!invitations.EnumerateArray().Any(o=>o.GetProperty("bookingId").GetInt64()==skillJob),"required skill excludes unqualified employees");}await using(var deadline=staff.Sql("UPDATE dispatch_jobs SET search_until=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND),offer_until=NULL WHERE booking_id=@id",("id",skillJob)))await deadline.ExecuteNonQueryAsync();var needsSupport=false;for(var attempt=0;attempt<30;attempt++){using var skillStatus=await direct.GetAsync("/internal/dispatch/"+skillJob);var data=await skillStatus.Content.ReadFromJsonAsync<JsonElement>();if(data.GetProperty("state").GetString()=="support"){needsSupport=true;break;}await Task.Delay(500);}Check(needsSupport,"missing required skills leads to admin support, not silent acceptance");
  await Request("PUT","/api/staff/admin/dispatch/services/77/skills",204,Array.Empty<long>(),admin);
  for(var index=0;index<3;index++)await SetPresence(index,false);
  var lateReady=await Register(1,9);var reachedFallback=false;
  for(var attempt=0;attempt<30;attempt++){using var statusResponse=await direct.GetAsync("/internal/dispatch/"+lateReady);var status=await statusResponse.Content.ReadFromJsonAsync<JsonElement>();if(status.GetProperty("round").GetInt32()>=3){Check(status.GetProperty("state").GetString()=="searching","empty initial groups must not end the overall search early");reachedFallback=true;break;}await Task.Delay(500);}
  Check(reachedFallback,"search reaches final area stage");await SetPresence(0,true);await Offer(workers[0].Token,lateReady);for(var index=1;index<3;index++)await SetPresence(index,true);
  Console.WriteLine("PASS: search remains open until its overall deadline and newly-ready staff receive invitations in the final stage.");
  Console.WriteLine("PASS: overlapping claims, expiry, readiness-off, admin/self race, cancellation tombstone, GPS quality/radius and required-skill filtering.");
  using(var streamRequest=new HttpRequestMessage(HttpMethod.Get,"/api/staff/me/dispatch/events")){streamRequest.Headers.Authorization=new("Bearer",workers[0].Token);using var stream=await http.SendAsync(streamRequest,HttpCompletionOption.ResponseHeadersRead);Check(stream.IsSuccessStatusCode&&stream.Content.Headers.ContentType?.MediaType=="text/event-stream","authenticated event stream");using var reader=new StreamReader(await stream.Content.ReadAsStreamAsync());var line=await reader.ReadLineAsync();Check(line?.StartsWith("data: ")==true,"stream starts with database snapshot");}
  await Request("GET","/api/staff/me/dispatch/offers",403,token:customer);await Request("GET","/api/staff/me/dispatch/offers",401);
  Check(Math.Abs(GeoMath.DistanceKm(10,106,10,106))<0.001,"same location distance");
  Check(Math.Abs(GeoMath.DistanceKm(0,0,1,0)-111.195)<0.01,"Haversine degree distance");
  Check(Math.Abs(GeoMath.DistanceKm(0,179,0,-179)-222.39)<0.02,"Haversine handles international date line");
  Console.WriteLine("PASS: authenticated realtime resynchronizes from database and offers enforce role access.");

  // New lifecycle cases use fresh days and only these isolated QA schemas.
  for(var i=0;i<workers.Length;i++)await SetPresence(i,true);
  async Task<long> AssignmentId(long booking,int worker){await using var q=staff.Sql("SELECT id FROM assignments WHERE booking_id=@id AND employee_id=@employee",("id",booking),("employee",ids[worker]));return Convert.ToInt64(await q.ExecuteScalarAsync());}
  async Task<(int Status,JsonElement Body)> Withdraw(long booking,int worker,string? operationKey=null)=>await Operation($"/api/orders/staff/orders/{booking}/withdraw",workers[worker].Token,new{assignmentId=await AssignmentId(booking,worker),reason="QA employee unexpected issue",idempotencyKey=operationKey??Guid.NewGuid().ToString("N")});
  async Task<(int Status,JsonElement Body)> Review(long booking,long request,long assignment,bool approve)=>await Operation($"/api/orders/admin/orders/{booking}/withdrawals/{request}/review",admin,new{assignmentId=assignment,approve,reason="QA admin reviewed evidence",idempotencyKey=Guid.NewGuid().ToString("N")});
  async Task Claim(long booking,int worker){var invitation=await Offer(workers[worker].Token,booking);Check((await Accept(workers[worker].Token,invitation.GetProperty("id").GetInt64(),Guid.NewGuid().ToString("N"))).Status==200,"QA lifecycle claim");}
  var triple=await Register(3,10);for(var i=0;i<3;i++)await Claim(triple,i);var withdrawKey=Guid.NewGuid().ToString("N");var withdrawn=await Withdraw(triple,0,withdrawKey);Check(withdrawn.Status==200,"early self withdrawal");Check((await Withdraw(triple,0,withdrawKey)).Body.GetProperty("id").GetString()==withdrawn.Body.GetProperty("id").GetString(),"withdrawal idempotency");Check(await Assigned(triple)==2,"three-person job keeps other two employees");
  var ownJobs=await Request("GET","/api/staff/me/jobs",200,token:workers[0].Token);Check(ownJobs.EnumerateArray().Single(j=>j.GetProperty("bookingId").GetInt64()==triple).GetProperty("status").GetString()=="cancelled","withdrawn slot released without erasing assignment");
  await Request("GET",$"/api/orders/staff/orders/{triple}/destination",404,token:workers[0].Token);
  var replacement=await Register(2,11);await Claim(replacement,0);await Claim(replacement,1);Check((await Withdraw(replacement,0)).Status==200,"replacement trigger");await Claim(replacement,2);Check(await Assigned(replacement)==2,"replacement fills exactly missing slot");
  var invitationsAfter=await Request("GET","/api/staff/me/dispatch/offers",200,token:workers[0].Token);Check(!invitationsAfter.EnumerateArray().Any(o=>o.GetProperty("bookingId").GetInt64()==replacement),"withdrawn employee excluded from automatic re-invitation");
  var near=await Register(1,12,DateTime.UtcNow.AddHours(1));await Claim(near,0);var nearResult=await Withdraw(near,0);Check(nearResult.Status==200&&nearResult.Body.GetProperty("result").GetProperty("withdrawalOutcome").GetString()=="requested","near-time withdrawal stays assigned");Check(await Assigned(near)==1,"request does not free a slot");var requestId=nearResult.Body.GetProperty("result").GetProperty("withdrawalRequestId").GetInt64();Check((await Review(near,requestId,await AssignmentId(near,0),false)).Status==200,"admin rejects withdrawal");Check(await Assigned(near)==1,"rejection retains assignment");
  var nearAgain=await Withdraw(near,0);requestId=nearAgain.Body.GetProperty("result").GetProperty("withdrawalRequestId").GetInt64();Check((await Review(near,requestId,await AssignmentId(near,0),true)).Status==200,"admin approves near-time withdrawal");Check(await Assigned(near)==0,"approved request releases only its assignment");
  var started=await Register(1,13);await Claim(started,0);var startedAssignment=await AssignmentId(started,0);Check((await Operation($"/api/orders/staff/orders/{started}/progress",workers[0].Token,new{assignmentId=startedAssignment,nextStatus="in_progress",idempotencyKey=Guid.NewGuid().ToString("N")})).Status==200,"start lifecycle work");var inWork=await Withdraw(started,0);Check(inWork.Body.GetProperty("result").GetProperty("withdrawalOutcome").GetString()=="requested"&&await Assigned(started)==1,"in-progress self-cancel requires review");requestId=inWork.Body.GetProperty("result").GetProperty("withdrawalRequestId").GetInt64();Check((await Review(started,requestId,startedAssignment,true)).Status==200,"admin replaces interrupted worker");await Claim(started,1);var detail=await Request("GET","/api/orders/admin/orders/"+started,200,token:admin);Check(detail.GetProperty("status").GetString()=="in_progress","replacement claim never resets order progress");
  foreach(var next in new[]{"in_progress","done"})Check((await Operation($"/api/orders/staff/orders/{started}/progress",workers[1].Token,new{assignmentId=await AssignmentId(started,1),nextStatus=next,idempotencyKey=Guid.NewGuid().ToString("N")})).Status==200,"replacement progresses correctly");Check((await Withdraw(started,1)).Status==409,"completed work cannot withdraw");
  var cancelJob=await Register(1,14);await Claim(cancelJob,0);var cancelKey=Guid.NewGuid().ToString("N");var raceCancel=await Task.WhenAll(Withdraw(cancelJob,0),Operation($"/api/orders/admin/orders/{cancelJob}/cancel",admin,new{reason="QA admin cancel while employee withdraws",idempotencyKey=cancelKey}));
  var ensureCancel=await Operation($"/api/orders/admin/orders/{cancelJob}/cancel",admin,new{reason="QA admin cancel while employee withdraws",idempotencyKey=cancelKey});Check(ensureCancel.Status==200,"admin cancellation reconciles concurrent withdrawal");Check(await Assigned(cancelJob)==0,"cancel/withdraw race leaves no assignments");
  var toStop=await Register(1,15);await Claim(toStop,0);await Operation($"/api/orders/staff/orders/{toStop}/progress",workers[0].Token,new{assignmentId=await AssignmentId(toStop,0),nextStatus="in_progress",idempotencyKey=Guid.NewGuid().ToString("N")});Check((await Operation($"/api/orders/admin/orders/{toStop}/cancel",admin,new{reason="QA cannot simple cancel started work",idempotencyKey=Guid.NewGuid().ToString("N")})).Status==409,"in-progress order requires stop process");Check((await Operation($"/api/orders/admin/orders/{toStop}/stop",admin,new{reason="QA admin stops and reconciles work",idempotencyKey=Guid.NewGuid().ToString("N")})).Status==200,"explicit admin stop preserves history");
  await Request("POST",$"/api/orders/admin/orders/{replacement}/cancel",403,new{reason="Unauthorized",idempotencyKey=Guid.NewGuid().ToString("N")},customer);
  await Request("POST",$"/api/orders/staff/orders/{replacement}/withdraw",404,new{assignmentId=await AssignmentId(replacement,1),reason="Foreign assignment",idempotencyKey=Guid.NewGuid().ToString("N")},workers[0].Token);
  await Request("POST",$"/api/orders/admin/orders/{cancelJob}/archive",403,new{reason="No admin permission"},customer);
  await Request("POST",$"/api/staff/admin/dispatch/jobs/{triple}/resume",204,token:admin);
  await Request("GET","/api/orders/notifications",200,token:customer);await Request("GET","/api/orders/notifications",403,token:workers[0].Token);
  var statsRange=$"?from={DateTime.UtcNow.AddDays(-1):yyyy-MM-dd}&to={start.AddDays(25):yyyy-MM-dd}&pageSize=100";
  var departingStats=await Request("GET","/api/orders/staff/me/statistics"+statsRange,200,token:workers[0].Token);Check(departingStats.GetProperty("summary").GetProperty("selfCancelled").GetInt32()>0,"statistics distinguish employee withdrawal");Check(!departingStats.GetProperty("history").GetProperty("items").EnumerateArray().Any(item=>item.GetProperty("id").GetInt64()==started),"withdrawn worker receives no completed allocation");
  var replacementStats=await Request("GET","/api/orders/staff/me/statistics"+statsRange,200,token:workers[1].Token);Check(replacementStats.GetProperty("summary").GetProperty("replacement").GetInt32()>0,"replacement assignment classified");var completedReplacement=replacementStats.GetProperty("history").GetProperty("items").EnumerateArray().Single(item=>item.GetProperty("id").GetInt64()==started);Check(completedReplacement.GetProperty("allocatedRevenue").GetDecimal()==600000,"allocation uses actual remaining completed staff only");
  await LifecycleArchiveChecks.RunAsync(orderConnection,cancelJob,replacement,1);
  var manualReplacement=await Register(1,16);await Claim(manualReplacement,0);var manualAssignment=await AssignmentId(manualReplacement,0);
  await Operation($"/api/orders/staff/orders/{manualReplacement}/progress",workers[0].Token,new{assignmentId=manualAssignment,nextStatus="in_progress",idempotencyKey=Guid.NewGuid().ToString("N")});
  var manualRequest=await Withdraw(manualReplacement,0);var manualRequestId=manualRequest.Body.GetProperty("result").GetProperty("withdrawalRequestId").GetInt64();Check((await Review(manualReplacement,manualRequestId,manualAssignment,true)).Status==200,"approve manual replacement vacancy");
  await using(var q=orders.Sql("UPDATE bookings SET scheduled_start=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 15 MINUTE),scheduled_end=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 2 HOUR) WHERE id=@id",("id",manualReplacement)))await q.ExecuteNonQueryAsync();
  await using(var q=staff.Sql("UPDATE dispatch_jobs SET payload=JSON_SET(payload,'$.start',DATE_FORMAT(DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 15 MINUTE),'%Y-%m-%dT%H:%i:%sZ'),'$.end',DATE_FORMAT(DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 2 HOUR),'%Y-%m-%dT%H:%i:%sZ')) WHERE booking_id=@id",("id",manualReplacement)))await q.ExecuteNonQueryAsync();
  Check((await Operation($"/api/orders/admin/orders/{manualReplacement}/assignments",admin,new{employeeIds=new[]{ids[1]},requiredSkillIds=Array.Empty<long>(),idempotencyKey=Guid.NewGuid().ToString("N")})).Status==200,"admin can manually fill approved vacancy during work");
  Check(await Assigned(manualReplacement)==1,"manual replacement still respects capacity");
  await using(var q=staff.Sql("SELECT COUNT(*) FROM assignments WHERE booking_id=@id AND employee_id=@employee AND scheduled_start>UTC_TIMESTAMP(6)",("id",manualReplacement),("employee",ids[1])))Check(Convert.ToInt64(await q.ExecuteScalarAsync())==1,"manual replacement saves the verified remaining interval, not the old start time");
  var finishedBeforeReview=await Register(1,17);await Claim(finishedBeforeReview,0);var finishAssignment=await AssignmentId(finishedBeforeReview,0);
  await Operation($"/api/orders/staff/orders/{finishedBeforeReview}/progress",workers[0].Token,new{assignmentId=finishAssignment,nextStatus="in_progress",idempotencyKey=Guid.NewGuid().ToString("N")});
  await Withdraw(finishedBeforeReview,0);
  await Operation($"/api/orders/staff/orders/{finishedBeforeReview}/progress",workers[0].Token,new{assignmentId=finishAssignment,nextStatus="done",idempotencyKey=Guid.NewGuid().ToString("N")});
  await using(var q=staff.Sql("SELECT COUNT(*) FROM assignment_withdrawals WHERE assignment_id=@id AND state='pending'",("id",finishAssignment)))Check(Convert.ToInt64(await q.ExecuteScalarAsync())==0,"completion closes obsolete withdrawal request without cancelling completed work");
  Console.WriteLine("PASS: early/near-time/in-progress withdrawals, admin review, multi-person replacement, privacy/calendar release, terminal guards, cancellation races and notification permissions.");

  async Task SetPresence(int index,bool ready){await using(var q=staff.Sql("UPDATE employee_presence SET updated_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 11 SECOND) WHERE employee_id=@id",("id",ids[index])))await q.ExecuteNonQueryAsync();await Request("PUT","/api/staff/me/dispatch/presence",200,new{ready,latitude=ready?(decimal?)10.7769m:null,longitude=ready?(decimal?)106.7009m:null,accuracy=ready?(int?)20:null,observedAt=ready?(DateTimeOffset?)DateTimeOffset.UtcNow:null},workers[index].Token);}
  async Task<long> Register(int count,int day,DateTime? at=null){var id=sequence++;var when=at??start.AddDays(day);await using(var q=orders.Sql("INSERT INTO bookings(id,customer_id,branch_id,address_snapshot,scheduled_start,scheduled_end,status,total_amount,code,subtotal_amount,discount_amount) SELECT @id,customer_id,@branch,'{\"recipient\":\"QA customer\",\"phone\":\"0901234567\",\"addressText\":\"Private QA destination\",\"latitude\":10.7769,\"longitude\":106.7009}',@start,@end,'confirmed',600000,@code,600000,0 FROM bookings WHERE id=1",("id",id),("branch",branch),("start",when),("end",when.AddHours(1)),("code","D-QA-"+id)))await q.ExecuteNonQueryAsync();
   using var r=await direct.PostAsJsonAsync("/internal/dispatch",new{bookingId=id,code="D-QA-"+id,branchId=branch,area="QA area",serviceId=77,serviceName="QA cleaning",start=when,end=when.AddHours(1),amount=600000,requiredStaff=count,latitude=10.7769m,longitude=106.7009m});Check(r.IsSuccessStatusCode,"register dispatch");return id;}
  async Task<JsonElement> Offer(string token,long booking){for(var i=0;i<30;i++){var list=await Request("GET","/api/staff/me/dispatch/offers",200,token:token);foreach(var offer in list.EnumerateArray())if(offer.GetProperty("bookingId").GetInt64()==booking)return offer.Clone();await Task.Delay(500);}throw new Exception("No eligible invitation for QA staff");}
  async Task<long> Assigned(long id){await using var q=staff.Sql("SELECT COUNT(*) FROM assignments WHERE booking_id=@id AND status<>'cancelled'",("id",id));return Convert.ToInt64(await q.ExecuteScalarAsync());}
  Task<(int Status,JsonElement Body)> Accept(string token,long id,string requestKey)=>Operation("/api/orders/dispatch/offers/"+id+"/accept",token,new{idempotencyKey=requestKey});
  async Task<(int Status,JsonElement Body)> Operation(string route,string token,object body){var response=await Send("POST",route,body,token);if(response.Status==202){var id=response.Body.GetProperty("id").GetString();for(var i=0;i<30;i++){await Task.Delay(300);var p=await Send("GET","/api/orders/operations/"+id,null,token);if(p.Body.GetProperty("state").GetString()=="succeeded")return(200,p.Body);if(p.Body.GetProperty("state").GetString()=="failed")return(p.Body.GetProperty("errorStatus").GetInt32(),p.Body);}}return response;}
  async Task<JsonElement> Request(string method,string path,int expected,object? body=null,string? token=null){var response=await Send(method,path,body,token);Check(response.Status==expected,$"{method} {path}: expected {expected}, got {response.Status}");return response.Body;}
  async Task<(int Status,JsonElement Body)> Send(string method,string path,object? body,string? token){using var request=new HttpRequestMessage(new(method),path);if(body is not null)request.Content=JsonContent.Create(body);if(token is not null)request.Headers.Authorization=new("Bearer",token);using var response=await http.SendAsync(request);var raw=await response.Content.ReadAsStringAsync();return((int)response.StatusCode,string.IsNullOrEmpty(raw)?default:JsonDocument.Parse(raw).RootElement.Clone());}
 }
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
}
